from dataclasses import dataclass

from Options import DefaultOnToggle, FreeText, OptionDict, PerGameCommonOptions, Range, Toggle


class Locations(OptionDict):
    """Generated by the Z2R app. Maps each location name to its RAM flag: {address, mask, collected}."""
    display_name = "locations"


class Rules(OptionDict):
    """Generated by the Z2R app. Maps each location (and the Great Palace boss) to its alternative routes,
    each a list of requirement names."""
    display_name = "rules"


class StartingItems(OptionDict):
    """Items the Z2R ROM starts with, as {item name: count}. Generated by the Z2R app."""
    display_name = "starting_items"


class StartMagicContainers(Range):
    """Magic containers the ROM starts with. Generated by the Z2R app."""
    display_name = "start_magic_containers"
    range_start = 0
    range_end = 8
    default = 4


class StartHeartContainers(Range):
    """Heart containers the ROM starts with. Generated by the Z2R app."""
    display_name = "start_heart_containers"
    range_start = 0
    range_end = 8
    default = 4


class ReplaceFireWithDash(Toggle):
    """Whether the Z2R app replaced the Fire spell with Dash. Generated by the Z2R app.
    When off, there is no Dash item and logic that needs Dash uses the Fairy spell instead."""
    display_name = "replace_fire_with_dash"


class CrystalsRequired(Range):
    """Crystals (palace bosses defeated) needed to enter the Great Palace and fight Thunderbird and Dark Link.
    Generated by the Z2R app."""
    display_name = "crystals_required"
    range_start = 0
    range_end = 6
    default = 6


class RomSeed(FreeText):
    """The seed text the Z2R app built the ROM from. The client refuses a ROM made from a different seed.
    Generated by the Z2R app."""
    display_name = "rom_seed"
    default = ""


class GreatPalace(FreeText):
    """The boss node of the Great Palace, which needs crystals_required other bosses defeated. Palaces can swap
    places, so this is not always EAST_GREAT_PALACE:boss. Generated by the Z2R app."""
    display_name = "great_palace"
    default = "EAST_GREAT_PALACE:boss"


class NewKasutoBasementRequirement(Range):
    """Magic containers needed for New Kasuto's basement to open. Generated by the Z2R app."""
    display_name = "new_kasuto_basement_requirement"
    range_start = 0
    range_end = 8
    default = 8


class IncludeSpellsInShuffle(DefaultOnToggle):
    """When off, the town wizards are not locations and the spells are not in the item pool.
    Generated by the Z2R app."""
    display_name = "include_spells_in_shuffle"


class IncludeSwordTechsInShuffle(DefaultOnToggle):
    """When off, the two sword technique trainers are not locations and Upstab and Downstab are not in the item
    pool. Generated by the Z2R app."""
    display_name = "include_sword_techs_in_shuffle"


class IncludeQuestItemsInShuffle(DefaultOnToggle):
    """When off, the Nabooru fountain, Bagu and the Saria table are not locations and Water, Bagu's Note and the
    Mirror are not in the item pool. Generated by the Z2R app."""
    display_name = "include_quest_items_in_shuffle"


class FixedItems(OptionDict):
    """Generated by the Z2R app. Maps each town spot left out of the shuffle to the item the game itself gives
    there, which logic needs to know about."""
    display_name = "fixed_items"


class RomHash(FreeText):
    """The six character hash the Z2R app shows on the title screen of the ROM. The client refuses a ROM with a
    different hash. Generated by the Z2R app."""
    display_name = "hash"
    default = ""


class Flags(FreeText):
    """The Z2R flag string, kept so the ROM can be regenerated. Not used by the world."""
    display_name = "flags"
    default = ""


class RandomizerVersion(FreeText):
    """The Z2R app version, kept so the ROM can be regenerated. Not used by the world."""
    display_name = "randomizer_version"
    default = ""


class FormatVersion(Range):
    """Version of the YAML layout the Z2R app wrote. Generated by the Z2R app."""
    display_name = "format_version"
    range_start = 1
    range_end = 99
    default = 1


@dataclass
class Z2ROptions(PerGameCommonOptions):
    locations: Locations
    rules: Rules
    starting_items: StartingItems
    start_magic_containers: StartMagicContainers
    start_heart_containers: StartHeartContainers
    replace_fire_with_dash: ReplaceFireWithDash
    crystals_required: CrystalsRequired
    great_palace: GreatPalace
    new_kasuto_basement_requirement: NewKasutoBasementRequirement
    include_spells_in_shuffle: IncludeSpellsInShuffle
    include_sword_techs_in_shuffle: IncludeSwordTechsInShuffle
    include_quest_items_in_shuffle: IncludeQuestItemsInShuffle
    fixed_items: FixedItems
    rom_seed: RomSeed
    hash: RomHash
    flags: Flags
    randomizer_version: RandomizerVersion
    format_version: FormatVersion
